import 'package:supabase_flutter/supabase_flutter.dart';
import 'package:uuid/uuid.dart';
import '../config/app_config.dart'; import '../config/supabase_config.dart'; import '../models/message.dart';
class ChatRepository { SupabaseClient get c=>SupabaseConfig.client; Future<String?>getOrCreate(String userId)async{if(AppConfig.demoMode)return 'demo-conversation'; final r=await c.rpc('get_or_create_conversation',params:{'pid':userId}); return r as String;} Future<Message?>send(String conversationId,String content)async{if(AppConfig.demoMode)return null; final id=const Uuid().v4(); final r=await c.rpc('send_message',params:{'cid':conversationId,'body':content.trim(),'client_id':id}); return r==null?null:Message.fromMap(r as Map<String,dynamic>);} Future<List<Message>>messages(String id,{DateTime?before,int limit=50})async{if(AppConfig.demoMode)return []; final r=await c.rpc('get_messages',params:{'p_conversation_id':id,'p_before':before?.toIso8601String(),'p_limit':limit}); return (r as List).map((e)=>Message.fromMap(e)).toList();} Future<void>read(String id)async{if(!AppConfig.demoMode)await c.rpc('mark_conversation_read',params:{'cid':id});}}
